import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import Footer from './components/Footer';
import Home from './pages/Home';
import Blog from './pages/Blog';
import Podcast from './pages/Podcast';
import Books from './pages/Books';
import Merch from './pages/Merch';
import About from './pages/About';
import Connect from './pages/Connect';
import Login from './pages/Admin/Login';
import Dashboard from './pages/Admin/Dashboard';

const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(true);

  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  return (
    <HashRouter>
      <div className="min-h-screen flex flex-col">
        <Navbar isDarkMode={isDarkMode} toggleTheme={toggleTheme} />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<Home />} />
            <Route path="/blog" element={<Blog />} />
            <Route path="/podcast" element={<Podcast />} />
            <Route path="/books" element={<Books />} />
            <Route path="/merch" element={<Merch />} />
            <Route path="/about" element={<About />} />
            <Route path="/connect" element={<Connect />} />

            {/* Hidden Admin Login */}
            <Route path="/veilcipher/login" element={<Login />} />
            <Route path="/admin/dashboard" element={<Dashboard />} />

            <Route path="*" element={<Navigate to="/" replace />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </HashRouter>
  );
};

export default App;

import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';

interface NavbarProps {
  isDarkMode: boolean;
  toggleTheme: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ isDarkMode, toggleTheme }) => {
  const [isOpen, setIsOpen] = useState(false);
  const location = useLocation();

  const navLinks = [
    { name: 'Home', path: '/' },
    { name: 'Blog', path: '/blog' },
    { name: 'Podcast', path: '/podcast' },
    { name: 'Books', path: '/books' },
    { name: 'Merch', path: '/merch' },
    { name: 'About', path: '/about' },
    { name: 'Connect', path: '/connect' },
  ];

  const isActive = (path: string) => location.pathname === path;

  return (
    <nav className="fixed top-0 w-full z-50 backdrop-blur-lg bg-white/80 dark:bg-slate-950/80 border-b border-slate-200 dark:border-slate-800">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          <div className="flex items-center">
            <Link to="/" className="flex items-center space-x-2">
              <div className="w-10 h-10 rounded-full gradient-bg flex items-center justify-center">
                <span className="text-white font-orbitron font-bold text-xl">TT</span>
              </div>
              <span className="font-orbitron font-bold text-xl hidden md:block">
                <span className="text-brand-start">TRICK</span> THEOLOGY
              </span>
            </Link>
          </div>

          <div className="hidden md:flex items-center space-x-6">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`text-sm font-medium transition-colors hover:text-brand-start ${
                  isActive(link.path) ? 'text-brand-start' : 'text-slate-600 dark:text-slate-300'
                }`}
              >
                {link.name}
              </Link>
            ))}

            <button
              onClick={toggleTheme}
              className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors"
            >
              {isDarkMode ? '🌞' : '🌙'}
            </button>
          </div>

          <div className="md:hidden flex items-center space-x-4">
            <button
              onClick={toggleTheme}
              className="p-2 rounded-lg bg-slate-100 dark:bg-slate-800"
            >
              {isDarkMode ? '🌞' : '🌙'}
            </button>
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="p-2 rounded-lg text-slate-600 dark:text-slate-300"
            >
              <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                {isOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="md:hidden bg-white dark:bg-slate-950 border-b border-slate-200 dark:border-slate-800">
          <div className="px-2 pt-2 pb-3 space-y-1">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                onClick={() => setIsOpen(false)}
                className={`block px-3 py-2 rounded-md text-base font-medium ${
                  isActive(link.path)
                    ? 'bg-brand-start/10 text-brand-start'
                    : 'text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-900'
                }`}
              >
                {link.name}
              </Link>
            ))}
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { MERCH } from '../constants';

const headlines = [
  "Unlocking Biblical Secrets",
  "Unsealing Biblical Secrets",
  "Unlocking Biblical Truths",
  "Exposing Theological Tricks",
  "Liberating the Masses"
];

const Home: React.FC = () => {
  const [displayText, setDisplayText] = useState("");
  const [headlineIndex, setHeadlineIndex] = useState(0);
  const [charIndex, setCharIndex] = useState(0);
  const [isDeleting, setIsDeleting] = useState(false);

  useEffect(() => {
    const currentHeadline = headlines[headlineIndex];
    const typeSpeed = isDeleting ? 50 : 100;

    const timeout = setTimeout(() => {
      if (!isDeleting && charIndex < currentHeadline.length) {
        setDisplayText(prev => prev + currentHeadline[charIndex]);
        setCharIndex(prev => prev + 1);
      } else if (isDeleting && charIndex > 0) {
        setDisplayText(prev => prev.slice(0, -1));
        setCharIndex(prev => prev - 1);
      } else if (!isDeleting && charIndex === currentHeadline.length) {
        setTimeout(() => setIsDeleting(true), 2000);
      } else if (isDeleting && charIndex === 0) {
        setIsDeleting(false);
        setHeadlineIndex(prev => (prev + 1) % headlines.length);
      }
    }, typeSpeed);

    return () => clearTimeout(timeout);
  }, [charIndex, isDeleting, headlineIndex]);

  return (
    <div className="flex flex-col">
      {/* Hero Section */}
      <section className="relative min-h-[85vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] bg-brand-start/20 rounded-full blur-[120px]"></div>
          <div className="absolute bottom-0 right-0 w-[400px] h-[400px] bg-brand-end/30 rounded-full blur-[100px]"></div>
        </div>

        <div className="relative z-10 max-w-7xl mx-auto px-4 text-center">
          <h1 className="font-orbitron font-black text-5xl md:text-8xl mb-8 leading-tight tracking-tighter">
            <span className="wipe-text block animate-wipe-in">
              {displayText}
              <span className="typing-cursor"></span>
            </span>
          </h1>
          <p className="text-lg md:text-2xl text-slate-500 dark:text-slate-400 mb-12 max-w-2xl mx-auto font-light leading-relaxed">
            The central digital headquarters for prophecy, wisdom, and theological revelation in the high-tech age.
          </p>
          <div className="flex flex-col sm:flex-row gap-4 justify-center">
            <Link to="/blog" className="px-8 py-4 gradient-bg text-white font-orbitron font-bold rounded-full hover:scale-105 transition-transform shadow-xl shadow-brand-start/20">
              EXPLORE TRUTH
            </Link>
            <Link to="/books" className="px-8 py-4 border-2 border-slate-200 dark:border-slate-800 text-slate-900 dark:text-white font-orbitron font-bold rounded-full hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors">
              VIEW BOOKS
            </Link>
          </div>
        </div>
      </section>

      {/* Merch Strip */}
      <section className="bg-slate-50 dark:bg-slate-900/50 py-16 overflow-hidden">
        <div className="max-w-7xl mx-auto px-4 mb-8 flex justify-between items-end">
          <h2 className="font-orbitron font-bold text-2xl tracking-widest text-brand-start">FEATURED MERCH</h2>
          <Link to="/merch" className="text-sm font-bold underline hover:text-brand-start">SHOP ALL</Link>
        </div>

        <div className="relative flex whitespace-nowrap overflow-hidden">
          <div className="flex animate-slide-left hover:[animation-play-state:paused]">
            {[...MERCH, ...MERCH].map((item, idx) => (
              <a
                key={`${item.id}-${idx}`}
                href={item.link}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block mx-4 w-64 md:w-80 bg-white dark:bg-slate-950 rounded-2xl overflow-hidden shadow-lg card-glow transition-all"
              >
                <div className="aspect-[4/5] relative overflow-hidden">
                  <img src={item.image} alt={item.title} className="w-full h-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent flex flex-col justify-end p-6 opacity-0 hover:opacity-100 transition-opacity">
                    <p className="text-white font-bold text-lg">{item.title}</p>
                    <p className="text-slate-300 text-sm">View on TeePublic</p>
                  </div>
                </div>
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* Philosophy Section */}
      <section className="py-24 max-w-5xl mx-auto px-4 text-center">
        <div className="inline-block p-1 mb-8 rounded-full gradient-bg">
          <div className="px-4 py-1 bg-white dark:bg-slate-950 rounded-full">
            <span className="text-xs font-orbitron font-bold tracking-[0.3em] text-brand-start">VISION</span>
          </div>
        </div>
        <h2 className="font-orbitron font-bold text-4xl mb-6">High-Tech Theology Meets Digital Prophecy</h2>
        <p className="text-xl text-slate-500 dark:text-slate-400 leading-relaxed italic font-light">
          "The secrets of the ages are no longer locked in dusty libraries. They are encoded in the fabric of our digital reality, waiting for those with the keys to unlock them."
        </p>
      </section>
    </div>
  );
};

