      } else if (!isDeleting && charIndex === currentHeadline.length) {
        setTimeout(() => setIsDeleting(true), 2000);
      } else if (isDeleting && charIndex === 0) {
        setIsDeleting(false);
        setHeadlineIndex(prev => (prev + 1) % headlines.length);
