    link: '', 
    platform: 'TeePublic' as 'TeePublic' | 'Redbubble' 
  });

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'book' | 'merch') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'book') {
          setBookForm(prev => ({ ...prev, image: base64String }));
        } else {
          setMerchForm(prev => ({ ...prev, image: base64String }));
        }
      };
      reader.readAsDataURL(file);
    }
