import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { BRAND_LOGO_URL } from '../../constants';

const Login: React.FC = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [lockoutTimeLeft, setLockoutTimeLeft] = useState(0);
  const navigate = useNavigate();

  // Load state from localStorage on mount
  useEffect(() => {
    const checkLockout = () => {
      const lockoutUntil = localStorage.getItem('tt_lockout_until');
      if (lockoutUntil) {
        const remaining = Math.ceil((parseInt(lockoutUntil) - Date.now()) / 1000);
        if (remaining > 0) {
          setLockoutTimeLeft(remaining);
        } else {
          setLockoutTimeLeft(0);
        }
      }
    };

    checkLockout();
    const timer = setInterval(checkLockout, 1000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    if (lockoutTimeLeft > 0) return;

    // Security check for Gmail
    if (!email.endsWith("@gmail.com")) {
      setError("ACCESS DENIED: Credentials must originate from a verified Gmail node.");
      return;
    }

    // Mock verification
    if (email === "admin@gmail.com" && password === "veilcipher") {
      // Clear security logs on successful login
      localStorage.removeItem('tt_failed_attempts');
      localStorage.removeItem('tt_lockout_until');
      navigate("/admin/dashboard");
    } else {
      const currentAttempts = parseInt(localStorage.getItem('tt_failed_attempts') || "0") + 1;
      localStorage.setItem('tt_failed_attempts', currentAttempts.toString());

      if (currentAttempts >= 3) {
        // Calculate lockout duration: 60s for first time, +300s for subsequent
        const penaltyBase = 60;
        const escalatingPenalty = (currentAttempts - 3) * 300;
        const totalPenalty = penaltyBase + escalatingPenalty;

        const lockoutUntil = Date.now() + (totalPenalty * 1000);
        localStorage.setItem('tt_lockout_until', lockoutUntil.toString());
        setLockoutTimeLeft(totalPenalty);
        setError(`CRITICAL: Brute-force signature detected. Terminal locked for ${totalPenalty}s.`);
      } else {
        setError(`INVALID CIPHER: Attempt ${currentAttempts} of 3 before terminal lockout.`);
      }
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4 font-exo">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-[40px] p-8 md:p-12 shadow-2xl relative overflow-hidden">
        {/* Top accent bar */}
        <div className="absolute top-0 left-0 w-full h-1 gradient-bg"></div>

        {/* Scanning animation effect if locked */}
        {lockoutTimeLeft > 0 && (
          <div className="absolute inset-0 bg-red-500/5 pointer-events-none animate-pulse"></div>
        )}

        <div className="text-center mb-10">
          <div className="w-24 h-24 rounded-full overflow-hidden mx-auto mb-6 flex items-center justify-center border-2 border-brand-start shadow-lg shadow-brand-start/40 bg-slate-950">
            <img 
              src={BRAND_LOGO_URL} 
              alt="Trick Theology Logo" 
              className="w-full h-full object-cover scale-110"
            />
          </div>
          <h1 className="font-orbitron font-bold text-2xl text-white tracking-widest uppercase">Veil Authentication</h1>
          <p className="text-slate-500 text-xs mt-2 uppercase tracking-widest font-bold">Secure Command Entry</p>
        </div>

        {error && (
          <div className={`mb-6 p-4 border rounded-2xl text-sm text-center font-bold ${
            lockoutTimeLeft > 0 
              ? 'bg-red-500/10 border-red-500/50 text-red-500 animate-bounce' 
              : 'bg-brand-start/10 border-brand-start/50 text-brand-start'
          }`}>
            <span className="mr-2">⚠️</span>
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-6">
          <div className="group">
            <label className="block text-[10px] font-orbitron font-bold text-slate-500 group-focus-within:text-brand-start mb-2 uppercase tracking-[0.3em] transition-colors">Gmail Identity</label>
            <div className="relative">
              <input 
                type="email" 
                disabled={lockoutTimeLeft > 0}
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all disabled:opacity-50 disabled:cursor-not-allowed" 
                placeholder="admin@gmail.com" 
                required
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-700">@</div>
            </div>
          </div>

          <div className="group">
            <label className="block text-[10px] font-orbitron font-bold text-slate-500 group-focus-within:text-brand-start mb-2 uppercase tracking-[0.3em] transition-colors">Access Cipher</label>
            <input 
              type="password" 
              disabled={lockoutTimeLeft > 0}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all disabled:opacity-50 disabled:cursor-not-allowed" 
              placeholder="••••••••"
              required
            />
          </div>

          <button 
            type="submit" 
            disabled={lockoutTimeLeft > 0}
            className={`w-full py-5 rounded-2xl font-orbitron font-bold transition-all transform active:scale-95 flex items-center justify-center gap-3 ${
              lockoutTimeLeft > 0 
                ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700' 
                : 'gradient-bg text-white hover:shadow-2xl hover:shadow-brand-start/40'
            }`}
          >
            {lockoutTimeLeft > 0 ? (
              <>
                <span className="w-2 h-2 rounded-full bg-red-500 animate-ping"></span>
                VEIL LOCKED ({formatTime(lockoutTimeLeft)})
              </>
            ) : (
              'INITIATE ACCESS'
            )}
          </button>
        </form>

        <div className="mt-10 flex items-center justify-center gap-4">
          <div className="h-px flex-1 bg-slate-800"></div>
          <span className="text-slate-600 text-[9px] uppercase tracking-[0.4em] font-black">Encrypted Node</span>
          <div className="h-px flex-1 bg-slate-800"></div>
        </div>
      </div>
    </div>
  );
};

