import React, { createContext, useContext, useState, useEffect } from 'react';
import { BlogPost, MerchItem, Book, PodcastEpisode, Comment, Page } from '../types';
import { BLOG_POSTS, MERCH, BOOKS, PODCASTS, MOCK_COMMENTS } from '../constants';

interface DataContextType {
  posts: BlogPost[];
  merch: MerchItem[];
  books: Book[];
  podcasts: PodcastEpisode[];
  comments: Comment[];
  pages: Page[];
  addPost: (post: Omit<BlogPost, 'id' | 'date'>) => void;
  addPodcast: (podcast: Omit<PodcastEpisode, 'id'>) => void;
  addBook: (book: Omit<Book, 'id'>) => void;
  addMerch: (item: Omit<MerchItem, 'id'>) => void;
  addPage: (page: Omit<Page, 'id' | 'lastModified'>) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  updateCommentStatus: (id: string, status: 'approved' | 'pending') => void;
  deleteItem: (type: 'posts' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages', id: string) => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [posts, setPosts] = useState<BlogPost[]>(() => JSON.parse(localStorage.getItem('tt_posts') || JSON.stringify(BLOG_POSTS)));
  const [merch, setMerch] = useState<MerchItem[]>(() => JSON.parse(localStorage.getItem('tt_merch') || JSON.stringify(MERCH)));
  const [books, setBooks] = useState<Book[]>(() => JSON.parse(localStorage.getItem('tt_books') || JSON.stringify(BOOKS)));
  const [podcasts, setPodcasts] = useState<PodcastEpisode[]>(() => JSON.parse(localStorage.getItem('tt_podcasts') || JSON.stringify(PODCASTS)));
  const [comments, setComments] = useState<Comment[]>(() => JSON.parse(localStorage.getItem('tt_comments') || JSON.stringify(MOCK_COMMENTS)));
  const [pages, setPages] = useState<Page[]>(() => JSON.parse(localStorage.getItem('tt_pages') || '[]'));

  useEffect(() => {
    localStorage.setItem('tt_posts', JSON.stringify(posts));
    localStorage.setItem('tt_merch', JSON.stringify(merch));
    localStorage.setItem('tt_books', JSON.stringify(books));
    localStorage.setItem('tt_podcasts', JSON.stringify(podcasts));
    localStorage.setItem('tt_comments', JSON.stringify(comments));
    localStorage.setItem('tt_pages', JSON.stringify(pages));
  }, [posts, merch, books, podcasts, comments, pages]);

  const addPost = (post: Omit<BlogPost, 'id' | 'date'>) => {
    const newPost: BlogPost = { ...post, id: Date.now().toString(), date: new Date().toISOString().split('T')[0] };
    setPosts([newPost, ...posts]);
  };

  const addPodcast = (podcast: Omit<PodcastEpisode, 'id'>) => {
    const newPodcast: PodcastEpisode = { ...podcast, id: Date.now().toString() };
    setPodcasts([newPodcast, ...podcasts]);
  };

  const addBook = (book: Omit<Book, 'id'>) => {
    const newBook: Book = { ...book, id: Date.now().toString() };
    setBooks([newBook, ...books]);
  };

  const addMerch = (item: Omit<MerchItem, 'id'>) => {
    const newItem: MerchItem = { ...item, id: Date.now().toString() };
    setMerch([newItem, ...merch]);
  };

  const addPage = (page: Omit<Page, 'id' | 'lastModified'>) => {
    const newPage: Page = { ...page, id: Date.now().toString(), lastModified: new Date().toISOString() };
    setPages([newPage, ...pages]);
  };

  const updatePage = (id: string, updatedFields: Partial<Page>) => {
    setPages(pages.map(p => p.id === id ? { ...p, ...updatedFields, lastModified: new Date().toISOString() } : p));
  };

  const updateCommentStatus = (id: string, status: 'approved' | 'pending') => {
    setComments(comments.map(c => c.id === id ? { ...c, status } : c));
  };

  const deleteItem = (type: 'posts' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages', id: string) => {
    switch (type) {
      case 'posts': setPosts(posts.filter(i => i.id !== id)); break;
      case 'podcasts': setPodcasts(podcasts.filter(i => i.id !== id)); break;
      case 'books': setBooks(books.filter(i => i.id !== id)); break;
      case 'merch': setMerch(merch.filter(i => i.id !== id)); break;
      case 'comments': setComments(comments.filter(i => i.id !== id)); break;
      case 'pages': setPages(pages.filter(i => i.id !== id)); break;
    }
  };

  return (
    <DataContext.Provider value={{ 
      posts, merch, books, podcasts, comments, pages,
      addPost, addPodcast, addBook, addMerch, addPage, updatePage, updateCommentStatus, deleteItem 
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within a DataProvider');
  return context;
};

