            <div className="grid grid-cols-2 gap-4">
                {merch.map(item => (
                  <div key={item.id} className="bg-slate-900/50 p-4 border border-slate-800 rounded-2xl group relative overflow-hidden transition-all hover:border-brand-start/40">
