};

export default Dashboard;

import React, { useState, useRef } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';
import { useData } from '../../context/DataContext';
import { BlogCategory, Page, BlogPost } from '../../types';

const chartData = [
  { name: 'Mon', visitors: 4000, interactions: 2400 },
  { name: 'Tue', visitors: 3000, interactions: 1398 },
  { name: 'Wed', visitors: 2000, interactions: 9800 },
  { name: 'Thu', visitors: 2780, interactions: 3908 },
  { name: 'Fri', visitors: 1890, interactions: 4800 },
  { name: 'Sat', visitors: 2390, interactions: 3800 },
  { name: 'Sun', visitors: 3490, interactions: 4300 },
];

type Tab = 'analytics' | 'blog' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages';

const Dashboard: React.FC = () => {
  const { 
    posts, podcasts, books, merch, comments, pages,
    addPost, addPodcast, addBook, addMerch, addPage, updatePage, updateCommentStatus, deleteItem 
  } = useData();

  const [activeTab, setActiveTab] = useState<Tab>('analytics');
  const bookFileRef = useRef<HTMLInputElement>(null);
  const merchFileRef = useRef<HTMLInputElement>(null);
  const pageFileRef = useRef<HTMLInputElement>(null);

  const blogEditorRef = useRef<HTMLDivElement>(null);
  const pageEditorRef = useRef<HTMLDivElement>(null);

  // Form States
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'Truth' as BlogCategory, image: '' });
  const [podcastForm, setPodcastForm] = useState({ title: '', embedUrl: '', platform: 'YouTube' as any });
  const [bookForm, setBookForm] = useState({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' as any });
  const [merchForm, setMerchForm] = useState({ title: '', description: '', image: '', link: '', platform: 'TeePublic' as any });
  const [pageForm, setPageForm] = useState({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
  const [editingPageId, setEditingPageId] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'book' | 'merch' | 'page' | 'post') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'book') setBookForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'merch') setMerchForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'page') setPageForm(prev => ({ ...prev, featuredImage: base64String }));
        else if (type === 'post') setPostForm(prev => ({ ...prev, image: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const execCmd = (command: string, value: string = '', editor: 'blog' | 'page') => {
    document.execCommand(command, false, value);
    const targetRef = editor === 'blog' ? blogEditorRef : pageEditorRef;
    if (targetRef.current) {
      if (editor === 'blog') setPostForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
      else setPageForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
    }
  };

  const handleAddPost = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = blogEditorRef.current?.innerHTML || '';
    addPost({ ...postForm, content: finalContent });
    setPostForm({ title: '', excerpt: '', content: '', category: 'Truth', image: '' });
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = '';
  };

  // Fix: Implemented missing handleAddBook function
  const handleAddBook = (e: React.FormEvent) => {
    e.preventDefault();
    addBook(bookForm);
    setBookForm({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' });
    if (bookFileRef.current) bookFileRef.current.value = '';
  };

  const handleSavePage = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = pageEditorRef.current?.innerHTML || '';
    const payload = { ...pageForm, content: finalContent };
    if (editingPageId) updatePage(editingPageId, payload);
    else addPage(payload);
    resetPageForm();
  };

  const resetPageForm = () => {
    setPageForm({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
    setEditingPageId(null);
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = '';
    if (pageFileRef.current) pageFileRef.current.value = '';
  };

  const startEditingPage = (page: Page) => {
    setEditingPageId(page.id);
    setPageForm({
      title: page.title,
      slug: page.slug,
      featuredImage: page.featuredImage,
      seoExcerpt: page.seoExcerpt,
      content: page.content
    });
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = page.content;
    setActiveTab('pages');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const insertImage = (editor: 'blog' | 'page') => {
    const url = prompt("Enter Visual Data URL:");
    if (url) execCmd('insertImage', url, editor);
  };

  // Group pages for visibility
  const systemPages = pages.filter(p => p.slug === 'privacy-policy' || p.slug === 'terms-of-service');
  const customPages = pages.filter(p => p.slug !== 'privacy-policy' && p.slug !== 'terms-of-service');

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 md:p-10 font-exo">
      <div className="max-w-7xl mx-auto">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div>
            <h1 className="font-orbitron font-black text-4xl mb-2 tracking-tight text-white uppercase">Command Center</h1>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest text-slate-400">Protocol: <span className="text-slate-300">VEIL_ACTIVE</span></p>
            </div>
          </div>
          <div className="flex bg-slate-900/50 p-1.5 rounded-2xl overflow-x-auto border border-slate-800 backdrop-blur-xl">
            {(['analytics', 'blog', 'podcasts', 'books', 'merch', 'pages', 'comments'] as Tab[]).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-orbitron font-bold uppercase tracking-widest transition-all whitespace-nowrap ${
                  activeTab === tab ? 'gradient-bg text-white shadow-lg shadow-brand-start/20' : 'text-slate-500 hover:text-white'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </header>

        {activeTab === 'analytics' && (
          <div className="animate-wipe-in">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
              {[
                { label: 'VISITOR COUNT', value: '124,502', trend: '+12%', color: 'text-brand-start' },
                { label: 'BLOG POSTS', value: posts.length, trend: `+${posts.length}`, color: 'text-blue-400' },
                { label: 'PAGES ACTIVE', value: pages.length, trend: `+${pages.length}`, color: 'text-purple-400' },
                { label: 'BOOKS ISSUED', value: books.length, trend: `+${books.length}`, color: 'text-orange-400' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900/50 border border-slate-800 p-6 rounded-3xl relative overflow-hidden group">
                  <p className="text-slate-500 font-orbitron font-bold text-[10px] tracking-widest mb-2 uppercase">{stat.label}</p>
                  <div className="flex items-end justify-between">
                    <span className={`text-3xl font-orbitron font-black ${stat.color}`}>{stat.value}</span>
                    <span className="text-green-500 text-xs font-bold">{stat.trend}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="bg-slate-900/50 border border-slate-800 p-8 rounded-[40px] backdrop-blur-md h-[400px]">
               <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <defs>
                      <linearGradient id="colorVis" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#c900ff" stopOpacity={0.3}/>
                        <stop offset="95%" stopColor="#c900ff" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                    <XAxis dataKey="name" stroke="#64748b" fontSize={10} axisLine={false} tickLine={false} />
                    <YAxis stroke="#64748b" fontSize={10} axisLine={false} tickLine={false} />
                    <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }} />
                    <Area type="monotone" dataKey="visitors" stroke="#c900ff" strokeWidth={3} fillOpacity={1} fill="url(#colorVis)" />
                  </AreaChart>
                </ResponsiveContainer>
            </div>
          </div>
        )}

        {activeTab === 'pages' && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-12 animate-wipe-in">
            <div className="xl:col-span-2 space-y-8">
              <div className="bg-slate-900/50 border border-slate-800 p-8 rounded-[40px]">
                <div className="flex items-center justify-between mb-8">
                  <h3 className="font-orbitron font-bold text-lg uppercase tracking-widest text-brand-start">
                    {editingPageId ? 'Edit Neural Node' : 'Neural Page Architect'}
                  </h3>
                  {editingPageId && (
                    <button onClick={resetPageForm} className="text-[10px] font-orbitron font-bold text-slate-400 hover:text-white uppercase tracking-widest">New Page Instead</button>
                  )}
