type Tab = 'analytics' | 'blog' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages';

const Dashboard: React.FC = () => {
  const { 
    posts, podcasts, books, merch, comments, pages,
    addPost, addPodcast, addBook, addMerch, addPage, updatePage, updateCommentStatus, deleteItem 
  } = useData();

  const [activeTab, setActiveTab] = useState<Tab>('analytics');
  const bookFileRef = useRef<HTMLInputElement>(null);
  const merchFileRef = useRef<HTMLInputElement>(null);
  const pageFileRef = useRef<HTMLInputElement>(null);

  const blogEditorRef = useRef<HTMLDivElement>(null);
  const pageEditorRef = useRef<HTMLDivElement>(null);

  // Form States
  const [postForm, setPostForm] = useState({ title: '', excerpt: '', content: '', category: 'Truth' as BlogCategory, image: '' });
  const [podcastForm, setPodcastForm] = useState({ title: '', embedUrl: '', platform: 'YouTube' as any });
  const [bookForm, setBookForm] = useState({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' as any });
  const [merchForm, setMerchForm] = useState({ title: '', description: '', image: '', link: '', platform: 'TeePublic' as any });
  const [pageForm, setPageForm] = useState({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
  const [editingPageId, setEditingPageId] = useState<string | null>(null);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'book' | 'merch' | 'page' | 'post') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'book') setBookForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'merch') setMerchForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'page') setPageForm(prev => ({ ...prev, featuredImage: base64String }));
        else if (type === 'post') setPostForm(prev => ({ ...prev, image: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const execCmd = (command: string, value: string = '', editor: 'blog' | 'page') => {
    document.execCommand(command, false, value);
    const targetRef = editor === 'blog' ? blogEditorRef : pageEditorRef;
    if (targetRef.current) {
      if (editor === 'blog') setPostForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
      else setPageForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
    }
  };

  const handleAddPost = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = blogEditorRef.current?.innerHTML || '';
    addPost({ ...postForm, content: finalContent });
    setPostForm({ title: '', excerpt: '', content: '', category: 'Truth', image: '' });
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = '';
  };

  // Fix: Added missing handleAddBook function
  const handleAddBook = (e: React.FormEvent) => {
    e.preventDefault();
    addBook(bookForm);
    setBookForm({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' as any });
    if (bookFileRef.current) bookFileRef.current.value = '';
  };

  const handleSavePage = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = pageEditorRef.current?.innerHTML || '';
    const payload = { ...pageForm, content: finalContent };
    if (editingPageId) updatePage(editingPageId, payload);
    else addPage(payload);
    resetPageForm();
  };

  const resetPageForm = () => {
    setPageForm({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
    setEditingPageId(null);
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = '';
    if (pageFileRef.current) pageFileRef.current.value = '';
  };

  const startEditingPage = (page: Page) => {
    setEditingPageId(page.id);
    setPageForm({
      title: page.title,
      slug: page.slug,
      featuredImage: page.featuredImage,
      seoExcerpt: page.seoExcerpt,
      content: page.content
    });
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = page.content;
    setActiveTab('pages');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const insertImage = (editor: 'blog' | 'page') => {
    const url = prompt("Enter Visual Data URL:");
    if (url) execCmd('insertImage', url, editor);
  };

  // Group pages for visibility
  const systemPages = pages.filter(p => p.slug === 'privacy-policy' || p.slug === 'terms-of-service');
  const customPages = pages.filter(p => p.slug !== 'privacy-policy' && p.slug !== 'terms-of-service');

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 md:p-10 font-exo">
