                        ))}
                        <button type="button" title="Insert Image" onClick={() => insertImage('page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start">🖼️</button>
                        <input type="color" title="Text Color" onChange={(e) => execCmd('foreColor', e.target.value, 'page')} className="w-10 h-10 bg-transparent border-none cursor-pointer p-0" />
                      </div>
                      <div ref={pageEditorRef} contentEditable className="min-h-[400px] p-8 outline-none text-slate-300 prose prose-invert prose-brand max-w-none" onInput={() => setPageForm(prev => ({ ...prev, content: pageEditorRef.current?.innerHTML || '' }))}></div>
                    </div>
                  </div>

                  <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.3em] hover:scale-[1.01] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                    {editingPageId ? 'Update Broadcast Signal' : 'Authorize Page Broadcast'}
                  </button>
                </form>
              </div>
            </div>

            <div className="space-y-8">
              <div>
                <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-brand-start mb-6">System Protocols</h3>
                <div className="space-y-4">
                  {systemPages.map(page => (
                    <div key={page.id} className="bg-slate-900/50 p-6 border border-brand-start/30 rounded-3xl group transition-all hover:bg-slate-900">
                      <div className="flex items-center gap-4 mb-4">
                        <div className="w-10 h-10 rounded-xl bg-brand-start/20 flex items-center justify-center text-brand-start">🛡️</div>
                        <div className="flex-grow">
                          <h4 className="font-orbitron font-bold text-sm text-white uppercase">{page.title}</h4>
                          <p className="text-[10px] text-slate-500 font-bold uppercase">/p/{page.slug}</p>
