                <form onSubmit={handleAddPost} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <input type="text" placeholder="Title of Revelation" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} required />
                    <select className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none appearance-none" value={postForm.category} onChange={e => setPostForm({...postForm, category: e.target.value as BlogCategory})}>
                      {['Wisdom', 'Truth', 'Secrets', 'Theological Tricks', 'Prophecy', 'Global Politics', 'Names and Codes'].map(c => <option key={c}>{c}</option>)}
                    </select>
                  </div>
                  <input type="text" placeholder="Featured Image URL" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={postForm.image} onChange={e => setPostForm({...postForm, image: e.target.value})} />
                  <textarea placeholder="Brief Summary" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white h-24 focus:ring-2 focus:ring-brand-start outline-none resize-none" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} required />
                  <div className="border border-slate-800 rounded-3xl overflow-hidden bg-slate-950">
