};

export default Dashboard;

export interface BlogPost {
  id: string;
  title: string;
  excerpt: string;
  content: string;
  category: BlogCategory;
  image: string;
  date: string;
}

export type BlogCategory = 
  | 'Wisdom' 
  | 'Truth' 
  | 'Secrets' 
