import React, { createContext, useContext, useState, useEffect } from 'react';
import { BlogPost, MerchItem, Book, PodcastEpisode, Comment, Page, AdminConfig } from '../types';
import { BLOG_POSTS, MERCH, BOOKS, PODCASTS, MOCK_COMMENTS, INITIAL_PAGES, DEFAULT_ADMIN } from '../constants';

interface DataContextType {
  posts: BlogPost[];
  merch: MerchItem[];
  books: Book[];
  podcasts: PodcastEpisode[];
  comments: Comment[];
  pages: Page[];
  adminConfig: AdminConfig;
  addPost: (post: Omit<BlogPost, 'id' | 'date'>) => void;
  updatePost: (id: string, post: Partial<BlogPost>) => void;
  addPodcast: (podcast: Omit<PodcastEpisode, 'id'>) => void;
  addBook: (book: Omit<Book, 'id'>) => void;
  addMerch: (item: Omit<MerchItem, 'id'>) => void;
  addPage: (page: Omit<Page, 'id' | 'lastModified'>) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  addComment: (comment: Omit<Comment, 'id' | 'status' | 'date'>) => void;
  updateCommentStatus: (id: string, status: 'approved' | 'pending') => void;
  deleteItem: (type: 'posts' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages', id: string) => void;
  updateAdmin: (config: AdminConfig) => void;
}

const DataContext = createContext<DataContextType | undefined>(undefined);

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // Robust initializers
  const getInitial = (key: string, fallback: any) => {
    try {
      const saved = localStorage.getItem(key);
      if (saved && saved !== 'undefined' && saved !== 'null') {
        return JSON.parse(saved);
      }
    } catch (e) {
      console.error(`Error loading ${key} from storage:`, e);
    }
    return fallback;
  };

  const [posts, setPosts] = useState<BlogPost[]>(() => getInitial('tt_posts', BLOG_POSTS));
  const [merch, setMerch] = useState<MerchItem[]>(() => getInitial('tt_merch', MERCH));
  const [books, setBooks] = useState<Book[]>(() => getInitial('tt_books', BOOKS));
  const [podcasts, setPodcasts] = useState<PodcastEpisode[]>(() => getInitial('tt_podcasts', PODCASTS));
  const [comments, setComments] = useState<Comment[]>(() => getInitial('tt_comments', MOCK_COMMENTS));
  const [adminConfig, setAdminConfig] = useState<AdminConfig>(() => getInitial('tt_admin_config', DEFAULT_ADMIN));
  const [pages, setPages] = useState<Page[]>(() => getInitial('tt_pages', INITIAL_PAGES));

  useEffect(() => {
    localStorage.setItem('tt_posts', JSON.stringify(posts));
    localStorage.setItem('tt_merch', JSON.stringify(merch));
    localStorage.setItem('tt_books', JSON.stringify(books));
    localStorage.setItem('tt_podcasts', JSON.stringify(podcasts));
    localStorage.setItem('tt_comments', JSON.stringify(comments));
    localStorage.setItem('tt_pages', JSON.stringify(pages));
    localStorage.setItem('tt_admin_config', JSON.stringify(adminConfig));
  }, [posts, merch, books, podcasts, comments, pages, adminConfig]);

  const addPost = (post: Omit<BlogPost, 'id' | 'date'>) => {
    const newPost: BlogPost = { ...post, id: Date.now().toString(), date: new Date().toISOString().split('T')[0] };
    setPosts([newPost, ...posts]);
  };

  const updatePost = (id: string, updatedFields: Partial<BlogPost>) => {
    setPosts(posts.map(p => p.id === id ? { ...p, ...updatedFields } : p));
  };

  const addPodcast = (podcast: Omit<PodcastEpisode, 'id'>) => {
    const newPodcast: PodcastEpisode = { ...podcast, id: Date.now().toString() };
    setPodcasts([newPodcast, ...podcasts]);
  };

  const addBook = (book: Omit<Book, 'id'>) => {
    const newBook: Book = { ...book, id: Date.now().toString() };
    setBooks([newBook, ...books]);
  };

  const addMerch = (item: Omit<MerchItem, 'id'>) => {
    const newItem: MerchItem = { ...item, id: Date.now().toString() };
    setMerch([newItem, ...merch]);
  };

  const addPage = (page: Omit<Page, 'id' | 'lastModified'>) => {
    const newPage: Page = { ...page, id: Date.now().toString(), lastModified: new Date().toISOString() };
    setPages([newPage, ...pages]);
  };

  const updatePage = (id: string, updatedFields: Partial<Page>) => {
    setPages(pages.map(p => p.id === id ? { ...p, ...updatedFields, lastModified: new Date().toISOString() } : p));
  };

  const addComment = (comment: Omit<Comment, 'id' | 'status' | 'date'>) => {
    const newComment: Comment = {
      ...comment,
      id: Date.now().toString(),
      status: 'pending',
      date: new Date().toISOString().split('T')[0]
    };
    setComments([newComment, ...comments]);
  };

  const updateCommentStatus = (id: string, status: 'approved' | 'pending') => {
    setComments(comments.map(c => c.id === id ? { ...c, status } : c));
  };

  const updateAdmin = (config: AdminConfig) => {
    setAdminConfig(config);
  };

  const deleteItem = (type: 'posts' | 'podcasts' | 'books' | 'merch' | 'comments' | 'pages', id: string) => {
    switch (type) {
      case 'posts': setPosts(posts.filter(i => i.id !== id)); break;
      case 'podcasts': setPodcasts(podcasts.filter(i => i.id !== id)); break;
      case 'books': setBooks(books.filter(i => i.id !== id)); break;
      case 'merch': setMerch(merch.filter(i => i.id !== id)); break;
      case 'comments': setComments(comments.filter(i => i.id !== id)); break;
      case 'pages': setPages(pages.filter(i => i.id !== id)); break;
    }
  };

  return (
    <DataContext.Provider value={{ 
      posts, merch, books, podcasts, comments, pages, adminConfig,
      addPost, updatePost, addPodcast, addBook, addMerch, addPage, updatePage, addComment, updateCommentStatus, deleteItem, updateAdmin 
    }}>
      {children}
    </DataContext.Provider>
  );
};

export const useData = () => {
  const context = useContext(DataContext);
  if (!context) throw new Error('useData must be used within a DataProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { BRAND_LOGO_URL, MASTER_RESET_SEED, DEFAULT_ADMIN } from '../../constants';
import { useData } from '../../context/DataContext';

const Login: React.FC = () => {
  const { adminConfig, updateAdmin } = useData();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [lockoutTimeLeft, setLockoutTimeLeft] = useState(0);
  const [isResetMode, setIsResetMode] = useState(false);
  const [resetSeed, setResetSeed] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const checkLockout = () => {
      const lockoutUntil = localStorage.getItem('tt_lockout_until');
      if (lockoutUntil) {
        const remaining = Math.ceil((parseInt(lockoutUntil) - Date.now()) / 1000);
        if (remaining > 0) {
          setLockoutTimeLeft(remaining);
        } else {
          setLockoutTimeLeft(0);
        }
      }
    };

    checkLockout();
    const timer = setInterval(checkLockout, 1000);
    return () => clearInterval(timer);
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();

    if (lockoutTimeLeft > 0) return;

    // Trim inputs to prevent whitespace errors
    const cleanEmail = email.trim();
    const cleanPassword = password.trim();

    if (!cleanEmail.endsWith("@gmail.com")) {
      setError("ACCESS DENIED: Credentials must originate from a verified Gmail node.");
      return;
    }

    // Direct comparison with adminConfig (or fallback to DEFAULT_ADMIN if state is empty)
    const targetEmail = adminConfig?.email || DEFAULT_ADMIN.email;
    const targetPassword = adminConfig?.passwordHash || DEFAULT_ADMIN.passwordHash;

    if (cleanEmail === targetEmail && cleanPassword === targetPassword) {
      localStorage.removeItem('tt_failed_attempts');
      localStorage.removeItem('tt_lockout_until');
      navigate("/admin/dashboard");
    } else {
      const currentAttempts = parseInt(localStorage.getItem('tt_failed_attempts') || "0") + 1;
      localStorage.setItem('tt_failed_attempts', currentAttempts.toString());

      if (currentAttempts >= 3) {
        const penaltyBase = 60;
        const escalatingPenalty = (currentAttempts - 3) * 300;
        const totalPenalty = penaltyBase + escalatingPenalty;

        const lockoutUntil = Date.now() + (totalPenalty * 1000);
        localStorage.setItem('tt_lockout_until', lockoutUntil.toString());
        setLockoutTimeLeft(totalPenalty);
        setError(`CRITICAL: Brute-force signature detected. Terminal locked for ${totalPenalty}s.`);
      } else {
        setError(`INVALID CIPHER: Attempt ${currentAttempts} of 3 before terminal lockout.`);
      }
    }
  };

  const handleMasterReset = (e: React.FormEvent) => {
    e.preventDefault();
    const cleanSeed = resetSeed.trim();
    if (cleanSeed === MASTER_RESET_SEED) {
      updateAdmin(DEFAULT_ADMIN);
      localStorage.removeItem('tt_failed_attempts');
      localStorage.removeItem('tt_lockout_until');
      setLockoutTimeLeft(0);
      setError("RECOVERY SUCCESSFUL: Protocols reset to default values. Access Granted.");
      setIsResetMode(false);
      setEmail(DEFAULT_ADMIN.email);
    } else {
      setError("RECOVERY FAILED: Master Seed rejected.");
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-slate-950 p-4 font-exo">
      <div className="w-full max-w-md bg-slate-900 border border-slate-800 rounded-[40px] p-8 md:p-12 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 gradient-bg"></div>

        {lockoutTimeLeft > 0 && !isResetMode && (
          <div className="absolute inset-0 bg-red-500/5 pointer-events-none animate-pulse"></div>
        )}

        <div className="text-center mb-10">
          <div className="w-24 h-24 rounded-full overflow-hidden mx-auto mb-6 flex items-center justify-center border-2 border-brand-start shadow-lg shadow-brand-start/40 bg-slate-950">
            <img 
              src={BRAND_LOGO_URL} 
              alt="Trick Theology Logo" 
              className="w-full h-full object-cover scale-110"
            />
          </div>
          <h1 className="font-orbitron font-bold text-2xl text-white tracking-widest uppercase">
            {isResetMode ? 'Master Recovery' : 'Authentication'}
          </h1>
          <p className="text-slate-500 text-xs mt-2 uppercase tracking-widest font-bold">
            {isResetMode ? 'Emergency Restoration protocol' : 'Secure Command Entry'}
          </p>
        </div>

        {error && (
          <div className={`mb-6 p-4 border rounded-2xl text-sm text-center font-bold uppercase tracking-widest leading-relaxed ${
            error.includes('SUCCESS') 
              ? 'bg-green-500/10 border-green-500/50 text-green-500' 
              : lockoutTimeLeft > 0 
                ? 'bg-red-500/10 border-red-500/50 text-red-500 animate-bounce' 
                : 'bg-brand-start/10 border-brand-start/50 text-brand-start'
          }`}>
            <span className="mr-2">{error.includes('SUCCESS') ? '✅' : '⚠️'}</span>
            {error}
          </div>
        )}

        {!isResetMode ? (
          <form onSubmit={handleLogin} className="space-y-6">
            <div className="group">
              <label className="block text-[10px] font-orbitron font-bold text-slate-500 group-focus-within:text-brand-start mb-2 uppercase tracking-[0.3em] transition-colors">Gmail Identity</label>
              <div className="relative">
                <input 
                  type="email" 
                  disabled={lockoutTimeLeft > 0}
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all disabled:opacity-50 disabled:cursor-not-allowed" 
                  placeholder="admin@gmail.com" 
                  required
                />
              </div>
            </div>

            <div className="group">
              <label className="block text-[10px] font-orbitron font-bold text-slate-500 group-focus-within:text-brand-start mb-2 uppercase tracking-[0.3em] transition-colors">Access Cipher</label>
              <input 
                type="password" 
                disabled={lockoutTimeLeft > 0}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-slate-950 border border-slate-800 rounded-2xl px-5 py-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all disabled:opacity-50 disabled:cursor-not-allowed" 
                placeholder="••••••••"
                required
              />
            </div>

            <button 
              type="submit" 
              disabled={lockoutTimeLeft > 0}
              className={`w-full py-5 rounded-2xl font-orbitron font-bold transition-all transform active:scale-95 flex items-center justify-center gap-3 ${
                lockoutTimeLeft > 0 
                  ? 'bg-slate-800 text-slate-500 cursor-not-allowed border border-slate-700' 
                  : 'gradient-bg text-white hover:shadow-2xl hover:shadow-brand-start/40'
              }`}
            >
              {lockoutTimeLeft > 0 ? (
                <>
                  <span className="w-2 h-2 rounded-full bg-red-500 animate-ping"></span>
                  VEIL LOCKED ({formatTime(lockoutTimeLeft)})
                </>
              ) : (
                'INITIATE ACCESS'
              )}
            </button>

            <div className="text-center">
              <button 
                type="button"
                onClick={() => setIsResetMode(true)}
                className="text-[9px] font-orbitron font-bold text-slate-600 hover:text-brand-start uppercase tracking-widest transition-colors"
              >
                Lost your Access Cipher? Reset Protocols
              </button>
            </div>
          </form>
        ) : (
          <form onSubmit={handleMasterReset} className="space-y-6">
            <div className="group">
              <label className="block text-[10px] font-orbitron font-bold text-slate-500 group-focus-within:text-brand-start mb-2 uppercase tracking-[0.3em] transition-colors">Master Recovery Seed</label>
              <input 
                type="password" 
                value={resetSeed}
                onChange={(e) => setResetSeed(e.target.value)}
