              <p className="text-[9px] text-slate-600 mt-2 italic uppercase tracking-widest text-center leading-relaxed">
                Reset will restore defaults and clear all security lockouts.
              </p>
            </div>

            <div className="flex flex-col gap-4">
              <button 
                type="submit" 
