  const [editingPageId, setEditingPageId] = useState<string | null>(null);

  // Security State
  const [securityForm, setSecurityForm] = useState({ currentPassword: '', newEmail: adminConfig.email, newPassword: '', confirmPassword: '' });
  const [securityStatus, setSecurityStatus] = useState({ msg: '', type: 'info' as 'info' | 'success' | 'error' });

  // Sync security form with adminConfig if config updates
  useEffect(() => {
    setSecurityForm(prev => ({ ...prev, newEmail: adminConfig.email }));
  }, [adminConfig.email]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, type: 'book' | 'merch' | 'page' | 'post') => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        if (type === 'book') setBookForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'merch') setMerchForm(prev => ({ ...prev, image: base64String }));
        else if (type === 'page') setPageForm(prev => ({ ...prev, featuredImage: base64String }));
        else if (type === 'post') setPostForm(prev => ({ ...prev, image: base64String }));
      };
      reader.readAsDataURL(file);
    }
  };

  const execCmd = (command: string, value: string = '', editor: 'blog' | 'page') => {
    document.execCommand(command, false, value);
    const targetRef = editor === 'blog' ? blogEditorRef : pageEditorRef;
    if (targetRef.current) {
      if (editor === 'blog') setPostForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
      else setPageForm(prev => ({ ...prev, content: targetRef.current!.innerHTML }));
    }
  };

  const handleSavePost = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = blogEditorRef.current?.innerHTML || '';
    const payload = { ...postForm, content: finalContent };

    if (editingPostId) {
      updatePost(editingPostId, payload);
    } else {
      addPost(payload);
    }

    resetPostForm();
  };

  const resetPostForm = () => {
    setPostForm({ title: '', excerpt: '', content: '', category: 'Truth', image: '' });
    setEditingPostId(null);
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = '';
  };

  const startEditingPost = (post: BlogPost) => {
    setEditingPostId(post.id);
    setPostForm({
      title: post.title,
      excerpt: post.excerpt,
      content: post.content,
      category: post.category,
      image: post.image
    });
    if (blogEditorRef.current) blogEditorRef.current.innerHTML = post.content;
    setActiveTab('blog');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddBook = (e: React.FormEvent) => {
    e.preventDefault();
    addBook(bookForm);
    setBookForm({ title: '', subtitle: '', description: '', image: '', buyLink: '', platform: 'Amazon' as any });
    if (bookFileRef.current) bookFileRef.current.value = '';
  };

  const handleAddMerch = (e: React.FormEvent) => {
    e.preventDefault();
    addMerch(merchForm);
    setMerchForm({ title: '', description: '', image: '', link: '', platform: 'TeePublic' as any });
    if (merchFileRef.current) merchFileRef.current.value = '';
  };

  const handleSavePage = (e: React.FormEvent) => {
    e.preventDefault();
    const finalContent = pageEditorRef.current?.innerHTML || '';
    const payload = { ...pageForm, content: finalContent };
    if (editingPageId) updatePage(editingPageId, payload);
    else addPage(payload);
    resetPageForm();
  };

  const resetPageForm = () => {
    setPageForm({ title: '', slug: '', featuredImage: '', seoExcerpt: '', content: '' });
    setEditingPageId(null);
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = '';
    if (pageFileRef.current) pageFileRef.current.value = '';
  };

  const startEditingPage = (page: Page) => {
    setEditingPageId(page.id);
    setPageForm({
      title: page.title,
      slug: page.slug,
      featuredImage: page.featuredImage,
      seoExcerpt: page.seoExcerpt,
      content: page.content
    });
    if (pageEditorRef.current) pageEditorRef.current.innerHTML = page.content;
    setActiveTab('pages');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleUpdateSecurity = (e: React.FormEvent) => {
    e.preventDefault();
    const cleanCurrent = securityForm.currentPassword.trim();
    if (cleanCurrent !== adminConfig.passwordHash) {
      setSecurityStatus({ msg: 'Current Access Cipher invalid. Authorization failed.', type: 'error' });
      return;
    }
    if (securityForm.newPassword !== securityForm.confirmPassword) {
      setSecurityStatus({ msg: 'New Ciphers do not match.', type: 'error' });
      return;
    }
    if (!securityForm.newEmail.trim().endsWith('@gmail.com')) {
      setSecurityStatus({ msg: 'Identity must be a verified Gmail node.', type: 'error' });
      return;
    }

    updateAdmin({
      email: securityForm.newEmail.trim(),
      passwordHash: securityForm.newPassword.trim() || adminConfig.passwordHash
    });

    setSecurityStatus({ msg: 'Veil Protocols Updated. Credentials Secured.', type: 'success' });
    setSecurityForm({ ...securityForm, currentPassword: '', newPassword: '', confirmPassword: '' });
  };

  const insertImage = (editor: 'blog' | 'page') => {
    const url = prompt("Enter Visual Data URL:");
    if (url) execCmd('insertImage', url, editor);
  };

  const systemPages = pages.filter(p => p.slug === 'privacy-policy' || p.slug === 'terms-of-service');
  const customPages = pages.filter(p => p.slug !== 'privacy-policy' && p.slug !== 'terms-of-service');

  return (
    <div className="min-h-screen bg-slate-950 text-white p-6 md:p-10 font-exo">
      <div className="max-w-7xl mx-auto">
        <header className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-12">
          <div>
            <h1 className="font-orbitron font-black text-4xl mb-2 tracking-tight text-white uppercase">Command Center</h1>
            <div className="flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-green-500 animate-pulse"></span>
              <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Protocol: <span className="text-slate-300">VEIL_ACTIVE</span></p>
            </div>
          </div>
          <div className="flex bg-slate-900/50 p-1.5 rounded-2xl overflow-x-auto border border-slate-800 backdrop-blur-xl">
            {(['analytics', 'blog', 'podcasts', 'books', 'merch', 'pages', 'comments', 'security'] as Tab[]).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`px-5 py-2.5 rounded-xl text-[10px] font-orbitron font-bold uppercase tracking-widest transition-all whitespace-nowrap ${
                  activeTab === tab ? 'gradient-bg text-white shadow-lg shadow-brand-start/20' : 'text-slate-500 hover:text-white'
                }`}
              >
                {tab}
              </button>
            ))}
          </div>
        </header>

        {activeTab === 'analytics' && (
          <div className="animate-wipe-in">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-12">
              {[
                { label: 'VISITOR COUNT', value: '124,502', trend: '+12%', color: 'text-brand-start' },
                { label: 'BLOG POSTS', value: posts.length, trend: `+${posts.length}`, color: 'text-blue-400' },
                { label: 'PAGES ACTIVE', value: pages.length, trend: `+${pages.length}`, color: 'text-purple-400' },
                { label: 'BOOKS ISSUED', value: books.length, trend: `+${books.length}`, color: 'text-orange-400' },
              ].map((stat, i) => (
                <div key={i} className="bg-slate-900/50 border border-slate-800 p-6 rounded-3xl relative overflow-hidden group">
                  <p className="text-slate-500 font-orbitron font-bold text-[10px] tracking-widest mb-2 uppercase">{stat.label}</p>
                  <div className="flex items-end justify-between">
                    <span className={`text-3xl font-orbitron font-black ${stat.color}`}>{stat.value}</span>
                    <span className="text-green-500 text-xs font-bold">{stat.trend}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="bg-slate-900/50 border border-slate-800 p-8 rounded-[40px] backdrop-blur-md h-[400px]">
               <ResponsiveContainer width="100%" height="100%">
                  <AreaChart data={chartData}>
                    <defs>
                      <linearGradient id="colorVis" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="5%" stopColor="#c900ff" stopOpacity={0.3}/>
                        <stop offset="95%" stopColor="#c900ff" stopOpacity={0}/>
                      </linearGradient>
                    </defs>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                    <XAxis dataKey="name" stroke="#64748b" fontSize={10} axisLine={false} tickLine={false} />
                    <YAxis stroke="#64748b" fontSize={10} axisLine={false} tickLine={false} />
                    <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155', borderRadius: '12px' }} />
                    <Area type="monotone" dataKey="visitors" stroke="#c900ff" strokeWidth={3} fillOpacity={1} fill="url(#colorVis)" />
                  </AreaChart>
                </ResponsiveContainer>
            </div>
          </div>
        )}

        {activeTab === 'blog' && (
           <div className="grid grid-cols-1 xl:grid-cols-3 gap-12 animate-wipe-in">
              <div className="xl:col-span-2 bg-slate-900/50 border border-slate-800 p-8 rounded-[40px]">
                <div className="flex items-center justify-between mb-8">
                  <h3 className="font-orbitron font-bold text-lg uppercase tracking-widest text-brand-start">
                    {editingPostId ? 'Edit Intel Node' : 'Unseal New Intel'}
                  </h3>
                  {editingPostId && (
                    <button onClick={resetPostForm} className="text-[10px] font-orbitron font-bold text-slate-400 hover:text-white uppercase tracking-widest">New Post Instead</button>
                  )}
                </div>
                <form onSubmit={handleSavePost} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <input type="text" placeholder="Title of Revelation" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={postForm.title} onChange={e => setPostForm({...postForm, title: e.target.value})} required />
                    <select className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none appearance-none" value={postForm.category} onChange={e => setPostForm({...postForm, category: e.target.value as BlogCategory})}>
                      {['Wisdom', 'Truth', 'Secrets', 'Theological Tricks', 'Prophecy', 'Global Politics', 'Names and Codes'].map(c => <option key={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Featured Asset URL</label>
                    <div className="flex gap-4">
                      <input type="text" placeholder="IMAGE URL" className="flex-grow bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={postForm.image} onChange={e => setPostForm({...postForm, image: e.target.value})} />
                      <input ref={blogFileRef} type="file" className="hidden" id="blog-img-upload" onChange={e => handleFileUpload(e, 'post')} />
                      <label htmlFor="blog-img-upload" className="px-6 py-4 bg-slate-900 border border-slate-800 rounded-xl font-bold text-xs cursor-pointer hover:bg-slate-800 transition-colors uppercase tracking-widest">Upload</label>
                    </div>
                  </div>
                  <textarea placeholder="Brief Summary" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white h-24 focus:ring-2 focus:ring-brand-start outline-none resize-none" value={postForm.excerpt} onChange={e => setPostForm({...postForm, excerpt: e.target.value})} required />
                  <div className="border border-slate-800 rounded-3xl overflow-hidden bg-slate-950">
                    <div className="bg-slate-900/60 p-3 border-b border-slate-800 flex flex-wrap gap-2 sticky top-0 z-10 backdrop-blur-md">
                      <button type="button" title="Bold" onClick={() => execCmd('bold', '', 'blog')} className="p-2 w-10 h-10 bg-slate-900/50 border border-slate-800 rounded-lg hover:text-brand-start font-bold transition-colors">B</button>
                      <button type="button" title="Italic" onClick={() => execCmd('italic', '', 'blog')} className="p-2 w-10 h-10 bg-slate-900/50 border border-slate-800 rounded-lg hover:text-brand-start italic transition-colors">I</button>
                      <button type="button" title="Underline" onClick={() => execCmd('underline', '', 'blog')} className="p-2 w-10 h-10 bg-slate-900/50 border border-slate-800 rounded-lg hover:text-brand-start underline transition-colors">U</button>
                      <div className="w-px h-10 bg-slate-800 mx-1"></div>
                      <button type="button" title="Insert Image" onClick={() => insertImage('blog')} className="p-2 w-10 h-10 bg-slate-900/50 border border-slate-800 rounded-lg hover:text-brand-start transition-colors">🖼️</button>
                    </div>
                    <div ref={blogEditorRef} contentEditable className="min-h-[400px] p-8 outline-none text-slate-300 prose prose-invert prose-brand max-w-none focus:bg-slate-900/20" onInput={() => setPostForm(prev => ({ ...prev, content: blogEditorRef.current?.innerHTML || '' }))}></div>
                  </div>
                  <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.3em] hover:scale-[1.02] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                    {editingPostId ? 'Update Broadcast Signal' : 'Broadcast To World Nodes'}
                  </button>
                </form>
              </div>
              <div className="space-y-6">
                <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-slate-600 mb-6">Archive List</h3>
                {posts.map(post => (
                  <div key={post.id} className="bg-slate-900/50 p-5 border border-slate-800 rounded-2xl flex items-center justify-between group hover:border-brand-start/50 transition-colors">
                    <div className="truncate flex-grow mr-4">
                      <p className="font-bold text-slate-200 truncate">{post.title}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">{post.category} • {post.date}</p>
                    </div>
                    <div className="flex gap-2">
                      <button onClick={() => startEditingPost(post)} className="p-2 bg-slate-950 border border-slate-800 rounded-lg text-[10px] font-bold hover:text-brand-start uppercase transition-colors">Edit</button>
                      <button onClick={() => deleteItem('posts', post.id)} className="p-2 text-red-500 hover:bg-red-500/10 rounded-lg transition-all">🗑️</button>
                    </div>
                  </div>
                ))}
              </div>
           </div>
        )}

        {activeTab === 'merch' && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-12 animate-wipe-in">
            <div className="xl:col-span-2 bg-slate-900/50 border border-slate-800 p-8 rounded-[40px]">
              <div className="flex items-center gap-4 mb-8">
                <div className="w-12 h-12 rounded-2xl gradient-bg flex items-center justify-center text-2xl">👕</div>
                <h3 className="font-orbitron font-bold text-lg uppercase tracking-widest text-brand-start">Deploy New Physical Artifact</h3>
              </div>

              <form onSubmit={handleAddMerch} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Product Title</label>
                    <input type="text" placeholder="PROPHECY SHIELD TEE" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={merchForm.title} onChange={e => setMerchForm({...merchForm, title: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Distribution Hub</label>
                    <select className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none appearance-none" value={merchForm.platform} onChange={e => setMerchForm({...merchForm, platform: e.target.value as any})}>
                      <option>TeePublic</option>
                      <option>Redbubble</option>
                    </select>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Direct Product URL (Buy Link)</label>
                  <input type="url" placeholder="https://teepublic.com/..." className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={merchForm.link} onChange={e => setMerchForm({...merchForm, link: e.target.value})} required />
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Thumbnail Asset (Visual URL)</label>
                  <div className="flex gap-4">
                    <input type="text" placeholder="IMAGE URL" className="flex-grow bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={merchForm.image} onChange={e => setMerchForm({...merchForm, image: e.target.value})} />
                    <input ref={merchFileRef} type="file" className="hidden" id="merch-img-upload" onChange={e => handleFileUpload(e, 'merch')} />
                    <label htmlFor="merch-img-upload" className="px-6 py-4 bg-slate-900 border border-slate-800 rounded-xl font-bold text-xs cursor-pointer hover:bg-slate-800 transition-colors uppercase tracking-widest">Upload</label>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Artifact Context (Brief Description)</label>
                  <textarea placeholder="High-performance theological apparel..." className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white h-24 focus:ring-2 focus:ring-brand-start outline-none resize-none" value={merchForm.description} onChange={e => setMerchForm({...merchForm, description: e.target.value})} required />
                </div>

                <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.3em] hover:scale-[1.01] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                  Broadcast Merch Node
                </button>
              </form>
            </div>

            <div className="space-y-6">
              <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-slate-600 mb-6">Artifact Archive</h3>
              <div className="grid grid-cols-1 gap-4">
                {merch.map(item => (
                  <div key={item.id} className="bg-slate-900/50 p-4 border border-slate-800 rounded-2xl flex gap-4 group hover:border-brand-start/50 transition-colors">
                    <img src={item.image} className="w-16 h-16 object-cover rounded-lg border border-slate-800" alt="" />
                    <div className="flex-grow min-w-0">
                      <h4 className="font-bold text-slate-200 truncate uppercase text-sm tracking-tight">{item.title}</h4>
                      <p className="text-[9px] text-brand-start font-bold uppercase tracking-widest mb-2">{item.platform}</p>
                      <button onClick={() => deleteItem('merch', item.id)} className="px-3 py-1 bg-red-500/10 text-red-500 rounded-md text-[9px] font-bold hover:bg-red-500/20 uppercase tracking-widest transition-all">Decommission</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'books' && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-12 animate-wipe-in">
            <div className="xl:col-span-2 bg-slate-900/50 border border-slate-800 p-8 rounded-[40px]">
              <div className="flex items-center gap-4 mb-8">
                <div className="w-12 h-12 rounded-2xl gradient-bg flex items-center justify-center text-2xl">📚</div>
                <h3 className="font-orbitron font-bold text-lg uppercase tracking-widest text-brand-start">Authorize Manuscript Release</h3>
              </div>

              <form onSubmit={handleAddBook} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Main Title</label>
                    <input type="text" placeholder="THE UNSEALED VEIL" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={bookForm.title} onChange={e => setBookForm({...bookForm, title: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Subtitle / Tagline</label>
                    <input type="text" placeholder="Decoding the Prophetic Frequency" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={bookForm.subtitle} onChange={e => setBookForm({...bookForm, subtitle: e.target.value})} />
                  </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Distribution Node</label>
                    <select className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none appearance-none" value={bookForm.platform} onChange={e => setBookForm({...bookForm, platform: e.target.value as any})}>
                      <option>Amazon</option>
                      <option>Google Play</option>
                      <option>PDF Download</option>
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Access URL (Buy Link)</label>
                    <input type="url" placeholder="https://amazon.com/..." className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={bookForm.buyLink} onChange={e => setBookForm({...bookForm, buyLink: e.target.value})} required />
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Manuscript Artifact (Cover Image)</label>
                  <div className="flex gap-4">
                    <input type="text" placeholder="IMAGE URL" className="flex-grow bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={bookForm.image} onChange={e => setBookForm({...bookForm, image: e.target.value})} />
                    <input ref={bookFileRef} type="file" className="hidden" id="book-img-upload" onChange={e => handleFileUpload(e, 'book')} />
                    <label htmlFor="book-img-upload" className="px-6 py-4 bg-slate-900 border border-slate-800 rounded-xl font-bold text-xs cursor-pointer hover:bg-slate-800 transition-colors uppercase tracking-widest">Upload Artifact</label>
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Prophetic Blurb (Short Description)</label>
                  <textarea placeholder="A groundbreaking exploration of biblical mysteries..." className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white h-32 focus:ring-2 focus:ring-brand-start outline-none resize-none" value={bookForm.description} onChange={e => setBookForm({...bookForm, description: e.target.value})} required />
                </div>

                <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.3em] hover:scale-[1.01] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                  Authorize Book Release
                </button>
              </form>
            </div>

            <div className="space-y-6">
              <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-slate-600 mb-6">Manuscript Archive</h3>
              <div className="grid grid-cols-1 gap-4">
                {books.map(book => (
                  <div key={book.id} className="bg-slate-900/50 p-4 border border-slate-800 rounded-2xl flex gap-4 group hover:border-brand-start/50 transition-colors">
                    <img src={book.image} className="w-16 h-24 object-cover rounded-lg border border-slate-800" alt="" />
                    <div className="flex-grow min-w-0">
                      <h4 className="font-bold text-slate-200 truncate uppercase text-sm tracking-tight">{book.title}</h4>
                      <p className="text-[9px] text-brand-start font-bold uppercase tracking-widest mb-2">{book.platform}</p>
                      <button onClick={() => deleteItem('books', book.id)} className="px-3 py-1 bg-red-500/10 text-red-500 rounded-md text-[9px] font-bold hover:bg-red-500/20 uppercase tracking-widest transition-all">Wipe Node</button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {activeTab === 'security' && (
          <div className="max-w-2xl mx-auto animate-wipe-in">
            <div className="bg-slate-900/50 border border-slate-800 p-12 rounded-[40px] shadow-2xl relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-1 gradient-bg opacity-50"></div>
              <div className="flex items-center gap-6 mb-12">
                <div className="w-16 h-16 rounded-3xl bg-brand-start/10 border border-brand-start/30 flex items-center justify-center text-3xl">🛡️</div>
                <div>
                  <h3 className="font-orbitron font-bold text-2xl uppercase tracking-widest text-white">Veil Protocols</h3>
                  <p className="text-slate-500 font-bold text-[10px] uppercase tracking-widest">Authorized Identity and Cipher Management</p>
                </div>
              </div>

              {securityStatus.msg && (
                <div className={`mb-8 p-4 border rounded-2xl text-xs font-bold uppercase tracking-widest flex items-center gap-3 ${
                  securityStatus.type === 'success' ? 'bg-green-500/10 border-green-500/30 text-green-500' : 
                  securityStatus.type === 'error' ? 'bg-red-500/10 border-red-500/30 text-red-500' : 'bg-brand-start/10 border-brand-start/30 text-brand-start'
                }`}>
                  <span className="text-xl">{securityStatus.type === 'success' ? '✅' : '⚠️'}</span>
                  {securityStatus.msg}
                </div>
              )}

              <form onSubmit={handleUpdateSecurity} className="space-y-8">
                <div className="space-y-2">
                  <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Current Authorized Identity</label>
                  <input type="email" disabled className="w-full bg-slate-950/50 border border-slate-800/50 rounded-xl p-4 text-slate-500 cursor-not-allowed outline-none" value={adminConfig.email} />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-brand-start uppercase tracking-widest ml-1">New Gmail Node</label>
                    <input type="email" placeholder="new-admin@gmail.com" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all" value={securityForm.newEmail} onChange={e => setSecurityForm({...securityForm, newEmail: e.target.value})} required />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-brand-start uppercase tracking-widest ml-1">Current Access Cipher</label>
                    <input type="password" placeholder="Verify Authority" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all" value={securityForm.currentPassword} onChange={e => setSecurityForm({...securityForm, currentPassword: e.target.value})} required />
                  </div>
                </div>

                <div className="h-px bg-slate-800 w-full my-4"></div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-400 uppercase tracking-widest ml-1">New Access Cipher</label>
                    <input type="password" placeholder="••••••••" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all" value={securityForm.newPassword} onChange={e => setSecurityForm({...securityForm, newPassword: e.target.value})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-400 uppercase tracking-widest ml-1">Confirm Cipher</label>
                    <input type="password" placeholder="••••••••" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none transition-all" value={securityForm.confirmPassword} onChange={e => setSecurityForm({...securityForm, confirmPassword: e.target.value})} />
                  </div>
                </div>

                <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.4em] hover:scale-[1.02] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                  Authorize Protocol Update
                </button>
              </form>
            </div>
          </div>
        )}

        {activeTab === 'pages' && (
          <div className="grid grid-cols-1 xl:grid-cols-3 gap-12 animate-wipe-in">
            <div className="xl:col-span-2 space-y-8">
              <div className="bg-slate-900/50 border border-slate-800 p-8 rounded-[40px]">
                <div className="flex items-center justify-between mb-8">
                  <h3 className="font-orbitron font-bold text-lg uppercase tracking-widest text-brand-start">
                    {editingPageId ? 'Edit Neural Node' : 'Neural Page Architect'}
                  </h3>
                  {editingPageId && (
                    <button onClick={resetPageForm} className="text-[10px] font-orbitron font-bold text-slate-400 hover:text-white uppercase tracking-widest">New Page Instead</button>
                  )}
                </div>

                <form onSubmit={handleSavePage} className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="space-y-2">
                      <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Header Title</label>
                      <input type="text" placeholder="THE NEW GENESIS" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={pageForm.title} onChange={e => setPageForm({...pageForm, title: e.target.value, slug: editingPageId ? pageForm.slug : e.target.value.toLowerCase().replace(/[^a-z0-9]/g, '-')})} required />
                    </div>
                    <div className="space-y-2">
                      <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Access Slug (/p/{pageForm.slug})</label>
                      <input type="text" placeholder="page-url-id" className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={pageForm.slug} onChange={e => setPageForm({...pageForm, slug: e.target.value.toLowerCase().replace(/[^a-z0-9]/g, '-')})} required />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Neural Summary (SEO)</label>
                    <textarea placeholder="Unveiling the frequency..." className="w-full bg-slate-950 border border-slate-800 rounded-xl p-4 text-white h-20 focus:ring-2 focus:ring-brand-start outline-none resize-none" value={pageForm.seoExcerpt} onChange={e => setPageForm({...pageForm, seoExcerpt: e.target.value})} required />
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Featured Asset URL</label>
                    <div className="flex gap-4">
                      <input type="text" placeholder="IMAGE URL" className="flex-grow bg-slate-950 border border-slate-800 rounded-xl p-4 text-white focus:ring-2 focus:ring-brand-start outline-none" value={pageForm.featuredImage} onChange={e => setPageForm({...pageForm, featuredImage: e.target.value})} />
                      <input ref={pageFileRef} type="file" className="hidden" id="page-img-upload" onChange={e => handleFileUpload(e, 'page')} />
                      <label htmlFor="page-img-upload" className="px-6 py-4 bg-slate-900 border border-slate-800 rounded-xl font-bold text-xs cursor-pointer hover:bg-slate-800 transition-colors uppercase tracking-widest">Upload</label>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-orbitron font-bold text-slate-500 uppercase tracking-widest ml-1">Content Matrix (Rich Text)</label>
                    <div className="border border-slate-800 rounded-3xl overflow-hidden bg-slate-950">
                      <div className="bg-slate-900/80 p-3 border-b border-slate-800 flex flex-wrap gap-2">
                        <button type="button" title="Bold" onClick={() => execCmd('bold', '', 'page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start font-bold">B</button>
                        <button type="button" title="Italic" onClick={() => execCmd('italic', '', 'page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start italic">I</button>
                        <button type="button" title="Underline" onClick={() => execCmd('underline', '', 'page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start underline">U</button>
                        <div className="w-px h-10 bg-slate-800 mx-1"></div>
                        {[1, 2, 3, 4, 5].map(n => (
                          <button key={n} type="button" title={`Header ${n}`} onClick={() => execCmd('formatBlock', `H${n}`, 'page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start font-bold text-xs">H{n}</button>
                        ))}
                        <button type="button" title="Insert Image" onClick={() => insertImage('page')} className="p-2 w-10 h-10 bg-slate-950 border border-slate-800 rounded-lg hover:text-brand-start">🖼️</button>
                        <input type="color" title="Text Color" onChange={(e) => execCmd('foreColor', e.target.value, 'page')} className="w-10 h-10 bg-transparent border-none cursor-pointer p-0" />
                      </div>
                      <div ref={pageEditorRef} contentEditable className="min-h-[400px] p-8 outline-none text-slate-300 prose prose-invert prose-brand max-w-none" onInput={() => setPageForm(prev => ({ ...prev, content: pageEditorRef.current?.innerHTML || '' }))}></div>
                    </div>
                  </div>

                  <button type="submit" className="w-full py-5 gradient-bg rounded-2xl font-orbitron font-black text-xs tracking-[0.3em] hover:scale-[1.01] transition-all shadow-2xl shadow-brand-start/20 uppercase">
                    {editingPageId ? 'Update Broadcast Signal' : 'Authorize Page Broadcast'}
                  </button>
                </form>
              </div>
            </div>

            <div className="space-y-8">
              <div>
                <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-brand-start mb-6">System Protocols</h3>
                <div className="space-y-4">
                  {systemPages.map(page => (
                    <div key={page.id} className="bg-slate-900/50 p-6 border border-brand-start/30 rounded-3xl group transition-all hover:bg-slate-900">
                      <div className="flex items-center gap-4 mb-4">
                        <div className="w-10 h-10 rounded-xl bg-brand-start/20 flex items-center justify-center text-brand-start">🛡️</div>
                        <div className="flex-grow">
                          <h4 className="font-orbitron font-bold text-sm text-white uppercase">{page.title}</h4>
                          <p className="text-[10px] text-slate-500 font-bold uppercase">/p/{page.slug}</p>
                        </div>
                        <button onClick={() => startEditingPage(page)} className="p-2 bg-slate-950 border border-slate-800 rounded-lg text-[10px] font-bold hover:text-brand-start uppercase transition-colors">Edit</button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div>
                <h3 className="font-orbitron font-bold text-xs uppercase tracking-[0.4em] text-slate-600 mb-6">Custom Neural Nodes</h3>
                <div className="space-y-4">
                  {customPages.length === 0 ? (
                    <div className="p-8 border-2 border-dashed border-slate-800 rounded-3xl text-center text-slate-600 text-[10px] uppercase font-bold tracking-widest">No custom nodes.</div>
                  ) : (
                    customPages.map(page => (
                      <div key={page.id} className="bg-slate-900/50 p-6 border border-slate-800 rounded-3xl group hover:border-brand-start/50 transition-all">
                        <div className="flex items-center gap-4 mb-4">
                          <img src={page.featuredImage} className="w-10 h-10 rounded-xl object-cover bg-slate-950 border border-slate-800" alt="" />
                          <div className="flex-grow">
                            <h4 className="font-orbitron font-bold text-sm text-white uppercase truncate">{page.title}</h4>
                            <p className="text-[10px] text-brand-start font-bold uppercase">/p/{page.slug}</p>
                          </div>
                        </div>
                        <div className="flex gap-2 pt-4 border-t border-slate-800">
                          <button onClick={() => startEditingPage(page)} className="flex-1 p-2 bg-slate-950 border border-slate-800 rounded-lg text-[10px] font-bold hover:text-brand-start uppercase">Edit</button>
                          <button onClick={() => deleteItem('pages', page.id)} className="p-2 bg-red-500/10 text-red-500 rounded-lg text-[10px] font-bold hover:bg-red-500/20 uppercase">Wipe</button>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
